def main():
  spec = {'voice': 'cedar', 'clips': [{'id': i, 'text': t} for i, _, t, _ in CLIPS]}
  (ROOT/'narration.json').write_text(json.dumps(spec, indent=2)+'\n')
  rows = ['# Nine multiplications, and not one fewer', '', '| Clip / scene | Exact narration | Animation / new understanding |', '|---|---|---|']
  rows += [f'| {i} / {s} | {t} | {v} |' for i, s, t, v in CLIPS]
  rows += ['', 'Comprehension review: arithmetic, polynomial slots, permitted products, grids and span are introduced in that order. The span container is explicitly schematic. The full subspace-completeness proof and additivity theorem are cited rather than implied by the drawings. Finite-field size four is distinguished from mod four. No unverified classical q=5 threshold is used.']
  (ROOT/'storyboard.md').write_text('\n'.join(rows)+'\n')
  print(len(CLIPS), 'clips;', sum(len(t.split()) for _,_,t,_ in CLIPS), 'words', flush=True)

if __name__ == '__main__':
  main()
